/// <summary>
/// Single source of truth for the HTTP surface exposed by <see cref="ControlServer"/>.
/// Every route the server dispatches is described here; <c>RouteAsync</c> matches
/// against these catalog paths, and <see cref="ControlIndexPage"/> renders them.
/// Adding a route here is required for it to appear on the index page.
/// </summary>
public static class ControlRoutes
{
    public sealed record RouteInfo(string Method, string Path, string DisplayPath, string Summary);

    public static readonly RouteInfo Index = new(
        "GET", "/", "/",
        "HTML index page documenting the API surface (routes and commands).");

    public static readonly RouteInfo Health = new(
        "GET", "/health", "/health",
        "Liveness check; returns {\"status\":\"ok\"}.");

    public static readonly RouteInfo State = new(
        "GET", "/state", "/state",
        "Full JSON snapshot: rootPath, isBusy, tasks, stages, commands map, and more.");

    public static readonly RouteInfo Screenshot = new(
        "GET", "/screenshot", "/screenshot[?path=…]",
        "Captures the live window as a PNG. Optional ?path writes the file and returns X-Screenshot-Path.");

    public static readonly RouteInfo Command = new(
        "POST", "/command/", "/command/{name}",
        "Invokes the named command (same as clicking its button). Disabled commands return 409.");

    public static readonly IReadOnlyList<RouteInfo> All { get; } =
        [Index, Health, State, Screenshot, Command];
}

