using System.Net;
using System.Text;

namespace VisualRelay.App.Services;

/// <summary>
/// Pure, static, UI-thread-free HTML renderer for the control API index page.
/// Every interpolated value is HTML-encoded; no route path or command name is
/// hand-typed — everything comes from the catalogs.
/// </summary>
public static class ControlIndexPage
{
    /// <summary>
    /// Renders a complete HTML5 document listing <paramref name="routes"/> and
    /// <paramref name="commandNames"/>. Accessible, no CSS, no JavaScript.
    /// </summary>
    public static string Render(IReadOnlyList<ControlRoutes.RouteInfo> routes, IReadOnlyList<string> commandNames)
    {
        var sb = new StringBuilder();

        sb.AppendLine("<!DOCTYPE html>");
        sb.AppendLine("<html lang=\"en\">");
        sb.AppendLine("<head>");
        sb.AppendLine("  <meta charset=\"utf-8\">");
        sb.AppendLine("  <title>Visual Relay — Control API</title>");
        sb.AppendLine("</head>");
        sb.AppendLine("<body>");
        sb.AppendLine("  <main>");
        sb.AppendLine("    <h1>Visual Relay Control API</h1>");
        sb.AppendLine("    <p>The Visual Relay control API is a localhost-only HTTP surface for driving the running app the");
        sb.AppendLine("       same way its on-screen buttons do: read live state, invoke commands, and capture screenshots.");
        sb.AppendLine("       It exists so scripts and agents can automate and observe the GUI with no human at the keyboard.");
        sb.AppendLine("       Every command maps to a real UI action and honors the same enabled/disabled gating as the");
        sb.AppendLine("       corresponding button.</p>");

        sb.AppendLine();
        sb.AppendLine("    <h2>Endpoints</h2>");
        sb.AppendLine("    <table>");
        sb.AppendLine("      <caption>HTTP endpoints exposed by the control API</caption>");
        sb.AppendLine("      <thead>");
        sb.AppendLine("        <tr><th scope=\"col\">Method</th><th scope=\"col\">Path</th><th scope=\"col\">Purpose</th></tr>");
        sb.AppendLine("      </thead>");
        sb.AppendLine("      <tbody>");

        foreach (var route in routes)
        {
            var method = WebUtility.HtmlEncode(route.Method);
            var displayPath = WebUtility.HtmlEncode(route.DisplayPath);
            var summary = WebUtility.HtmlEncode(route.Summary);
            sb.AppendLine($"        <tr><td><code>{method}</code></td><td><code>{displayPath}</code></td><td>{summary}</td></tr>");
        }

        sb.AppendLine("      </tbody>");
        sb.AppendLine("    </table>");

        sb.AppendLine();
        sb.AppendLine("    <h2>Commands</h2>");
        sb.AppendLine("    <p>Invoke with <code>POST /command/{name}</code>. Available names:</p>");
        sb.AppendLine("    <ul>");

        foreach (var name in commandNames)
        {
            var encoded = WebUtility.HtmlEncode(name);
            sb.AppendLine($"      <li><code>{encoded}</code></li>");
        }

        sb.AppendLine("    </ul>");
        sb.AppendLine("  </main>");
        sb.AppendLine("</body>");
        sb.AppendLine("</html>");

        return sb.ToString();
    }
}

